/**
 * Offline (bez sieci) walidacja identyfikatorow: REGON 9/14 i NIP.
 * Sluzy jako pierwszy, darmowy filtr przed odpytaniem API GUS.
 */

const WEIGHTS_REGON_9 = [8, 9, 2, 3, 4, 5, 6, 7];
const WEIGHTS_REGON_14 = [2, 4, 8, 5, 0, 9, 7, 3, 6, 1, 2, 4, 8];
const WEIGHTS_NIP = [6, 5, 7, 2, 3, 4, 5, 6, 7];

/** Usuwa spacje, myslniki i inne znaki nieliczbowe. */
export function normalizeDigits(value) {
  return String(value ?? '').replace(/\D/g, '');
}

function checksumMatches(digits, weights) {
  const sum = weights.reduce((acc, w, i) => acc + w * Number(digits[i]), 0);
  // reszta z 11; wynik 10 traktowany jest jak 0
  return (sum % 11) % 10 === Number(digits[weights.length]);
}

/** REGON 9-cyfrowy (podmiot) lub 14-cyfrowy (jednostka lokalna). */
export function isValidRegon(value) {
  const regon = normalizeDigits(value);
  if (regon.length === 9) return checksumMatches(regon, WEIGHTS_REGON_9);
  if (regon.length === 14) {
    return checksumMatches(regon.slice(0, 9), WEIGHTS_REGON_9)
      && checksumMatches(regon, WEIGHTS_REGON_14);
  }
  return false;
}

/** NIP 10-cyfrowy. Suma kontrolna rowna 10 oznacza numer niepoprawny. */
export function isValidNip(value) {
  const nip = normalizeDigits(value);
  if (nip.length !== 10) return false;
  const sum = WEIGHTS_NIP.reduce((acc, w, i) => acc + w * Number(nip[i]), 0);
  const control = sum % 11;
  return control !== 10 && control === Number(nip[9]);
}

/** KRS to 10 cyfr bez sumy kontrolnej - sprawdzamy tylko format. */
export function isValidKrs(value) {
  return /^\d{10}$/.test(normalizeDigits(value));
}

/** Rozpoznaje, czym jest podany ciag: 'regon' | 'regon14' | 'nip' | 'krs' | null. */
export function detectIdentifierType(value) {
  const digits = normalizeDigits(value);
  if (digits.length === 14 && isValidRegon(digits)) return 'regon14';
  if (digits.length === 9 && isValidRegon(digits)) return 'regon';
  if (digits.length === 10 && isValidNip(digits)) return 'nip';
  if (digits.length === 10) return 'krs';
  return null;
}

