/**
 * Minimalne parsowanie XML zwracanego przez BIR1.1 - bez zaleznosci zewnetrznych.
 * GUS zwraca plaski XML (<root><dane>...</dane></root>), wiec pelny parser
 * nie jest potrzebny.
 */

export function unescapeXml(text) {
  return String(text ?? '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&amp;/g, '&');
}

export function escapeXml(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

/** Zwraca zawartosc pierwszego znacznika o podanej nazwie (ignoruje prefiks ns). */
export function extractTag(xml, tagName) {
  const re = new RegExp(`<(?:\\w+:)?${tagName}[^>]*>([\\s\\S]*?)</(?:\\w+:)?${tagName}>`, 'i');
  const match = re.exec(String(xml ?? ''));
  return match ? match[1] : null;
}

/** Zamienia plaski blok XML na obiekt { nazwaZnacznika: wartosc }. */
export function parseFlatBlock(block) {
  const result = {};
  const re = /<([\w.:-]+)\s*(?:\/>|>([\s\S]*?)<\/\1>)/g;
  let match;
  while ((match = re.exec(block)) !== null) {
    const key = match[1].replace(/^\w+:/, '');
    const value = match[2] === undefined ? '' : unescapeXml(match[2]).trim();
    result[key] = value;
  }
  return result;
}

/** Parsuje <root><dane>...</dane><dane>...</dane></root> do tablicy obiektow. */
export function parseDaneRecords(xml) {
  const records = [];
  const re = /<dane>([\s\S]*?)<\/dane>/gi;
  let match;
  while ((match = re.exec(String(xml ?? ''))) !== null) {
    records.push(parseFlatBlock(match[1]));
  }
  return records;
}

