/**
 * Klient SOAP dla uslugi GUS BIR1.1 (wyszukiwarka REGON).
 * Bez zaleznosci - wymaga globalnego fetch (Node >= 18, Deno, Bun, Workers, przegladarka*).
 * (*) w przegladarce zablokuje CORS - uzywaj po stronie serwera.
 */

import { escapeXml, extractTag, parseDaneRecords, unescapeXml } from './xml.js';

export const ENDPOINTS = {
  prod: 'https://wyszukiwarkaregon.stat.gov.pl/wsBIR/UslugaBIRzewnPubl.svc',
  test: 'https://wyszukiwarkaregontest.stat.gov.pl/wsBIR/UslugaBIRzewnPubl.svc',
};

/** Klucz testowy udostepniony publicznie przez GUS - dziala tylko na endpoincie test. */
export const TEST_API_KEY = 'abcde12345abcde12345';

const NS_ENVELOPE = 'http://www.w3.org/2003/05/soap-envelope';
const NS_ADDRESSING = 'http://www.w3.org/2005/08/addressing';
const NS_BIR = 'http://CIS/BIR/PUBL/2014/07';
const NS_DATA_CONTRACT = 'http://CIS/BIR/PUBL/2014/07/DataContract';
const ACTION_PREFIX = 'http://CIS/BIR/PUBL/2014/07/IUslugaBIRzewnPubl';

/** Nazwy raportow pelnych wg typu podmiotu i silosu. */
export const REPORT_NAMES = {
  P: 'BIR11OsPrawna',
  LP: 'BIR11JednLokalnaOsPrawnej',
  LF: 'BIR11JednLokalnaOsFizycznej',
  F: {
    1: 'BIR11OsFizycznaDzialalnoscCeidg',
    2: 'BIR11OsFizycznaDzialalnoscRolnicza',
    3: 'BIR11OsFizycznaDzialalnoscPozostala',
    4: 'BIR11OsFizycznaDzialalnoscSkreslonaDo20141108',
    6: 'BIR11OsFizycznaDaneOgolne',
  },
};

/** Kody bledow zwracane w polu ErrorCode wyniku wyszukiwania. */
export const ERROR_CODES = {
  0: 'Brak bledu',
  1: 'Nieprawidlowy numer identyfikacyjny',
  2: 'Brak sesji lub sesja wygasla',
  4: 'Nie znaleziono podmiotu dla podanych kryteriow',
  5: 'Za duza liczba wynikow',
  7: 'Blednie podane parametry wyszukiwania',
};

export class GusError extends Error {
  constructor(message, { code = null, status = null, body = null } = {}) {
    super(message);
    this.name = 'GusError';
    this.code = code;
    this.status = status;
    this.body = body;
  }
}

export class GusClient {
  /**
   * @param {object} options
   * @param {string} options.apiKey       klucz uzytkownika BIR
   * @param {'prod'|'test'|string} [options.environment='prod'] lub pelny URL endpointu
   * @param {number} [options.timeoutMs=15000]
   * @param {typeof fetch} [options.fetchImpl]
   */
  constructor({ apiKey, environment = 'prod', timeoutMs = 15000, fetchImpl } = {}) {
    if (!apiKey) throw new GusError('Brak apiKey do uslugi GUS BIR1.1');
    this.apiKey = apiKey;
    this.endpoint = ENDPOINTS[environment] ?? environment;
    this.timeoutMs = timeoutMs;
    this.fetch = fetchImpl ?? globalThis.fetch;
    if (typeof this.fetch !== 'function') {
      throw new GusError('Brak implementacji fetch - podaj options.fetchImpl');
    }
    this.sid = null;
  }

  buildEnvelope(action, bodyXml) {
    return `<?xml version="1.0" encoding="UTF-8"?>`
      + `<soap:Envelope xmlns:soap="${NS_ENVELOPE}" xmlns:ns="${NS_BIR}" xmlns:dat="${NS_DATA_CONTRACT}">`
      + `<soap:Header xmlns:wsa="${NS_ADDRESSING}">`
      + `<wsa:To>${this.endpoint}</wsa:To>`
      + `<wsa:Action>${ACTION_PREFIX}/${action}</wsa:Action>`
      + `</soap:Header>`
      + `<soap:Body>${bodyXml}</soap:Body>`
      + `</soap:Envelope>`;
  }

  async call(action, bodyXml, { withSession = true } = {}) {
    const headers = {
      'Content-Type': `application/soap+xml; charset=UTF-8; action="${ACTION_PREFIX}/${action}"`,
    };
    if (withSession && this.sid) headers.sid = this.sid;

    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    let response;
    try {
      response = await this.fetch(this.endpoint, {
        method: 'POST',
        headers,
        body: this.buildEnvelope(action, bodyXml),
        signal: controller.signal,
      });
    } catch (error) {
      throw new GusError(`Blad polaczenia z GUS (${action}): ${error.message}`);
    } finally {
      clearTimeout(timer);
    }

    const text = await response.text();
    if (!response.ok) {
      throw new GusError(`GUS zwrocil HTTP ${response.status} dla ${action}`, {
        status: response.status,
        body: text.slice(0, 2000),
      });
    }
    const fault = extractTag(text, 'Reason') ?? extractTag(text, 'faultstring');
    if (fault) throw new GusError(`SOAP Fault z GUS (${action}): ${unescapeXml(fault).trim()}`, { body: text.slice(0, 2000) });

    const result = extractTag(text, `${action}Result`);
    return result === null ? '' : unescapeXml(result).trim();
  }

  /** Loguje sie i zapamietuje identyfikator sesji (sid). */
  async login() {
    const sid = await this.call(
      'Zaloguj',
      `<ns:Zaloguj><ns:pKluczUzytkownika>${escapeXml(this.apiKey)}</ns:pKluczUzytkownika></ns:Zaloguj>`,
      { withSession: false },
    );
    if (!sid) throw new GusError('Logowanie do GUS nieudane - sprawdz klucz API i srodowisko');
    this.sid = sid;
    return sid;
  }

  async ensureSession() {
    if (!this.sid) await this.login();
    return this.sid;
  }

  async logout() {
    if (!this.sid) return;
    const sid = this.sid;
    this.sid = null;
    await this.call('Wyloguj', `<ns:Wyloguj><ns:pIdentyfikatorSesji>${escapeXml(sid)}</ns:pIdentyfikatorSesji></ns:Wyloguj>`, { withSession: false });
  }

  /** GetValue - np. 'StatusUslugi' ('1' = dostepna), 'KomunikatKod', 'KomunikatTresc'. */
  async getValue(parameterName) {
    return this.call('GetValue', `<ns:GetValue><ns:pNazwaParametru>${escapeXml(parameterName)}</ns:pNazwaParametru></ns:GetValue>`);
  }

  /**
   * DaneSzukajPodmioty.
   * @param {{regon?:string, nip?:string, krs?:string, regony9zn?:string[], nipy?:string[], krsy?:string[]}} params
   * @returns {Promise<Array<object>>} rekordy podsumowujace
   */
  async search(params) {
    await this.ensureSession();
    const mapping = {
      regon: 'Regon',
      nip: 'Nip',
      krs: 'Krs',
      regony9zn: 'Regony9zn',
      regony14zn: 'Regony14zn',
      nipy: 'Nipy',
      krsy: 'Krsy',
    };
    const fields = Object.entries(params)
      .filter(([key, value]) => mapping[key] && value != null && value !== '')
      .map(([key, value]) => {
        const text = Array.isArray(value) ? value.join(',') : value;
        return `<dat:${mapping[key]}>${escapeXml(text)}</dat:${mapping[key]}>`;
      });
    if (fields.length === 0) throw new GusError('Nie podano zadnego kryterium wyszukiwania');

    const result = await this.call(
      'DaneSzukajPodmioty',
      `<ns:DaneSzukajPodmioty><ns:pParametryWyszukiwania>${fields.join('')}</ns:pParametryWyszukiwania></ns:DaneSzukajPodmioty>`,
    );

    const errorCode = extractTag(result, 'ErrorCode');
    if (errorCode && Number(errorCode) !== 0) {
      const code = Number(errorCode);
      if (code === 4) return []; // nie znaleziono - to nie jest blad techniczny
      if (code === 2) { // sesja wygasla - jedna proba ponowienia
        this.sid = null;
        await this.login();
        return this.search(params);
      }
      throw new GusError(
        extractTag(result, 'ErrorMessagePl') || ERROR_CODES[code] || `Blad GUS ${code}`,
        { code },
      );
    }
    return parseDaneRecords(result);
  }

  /** DanePobierzPelnyRaport - szczegolowe dane podmiotu. */
  async fullReport(regon, reportName) {
    await this.ensureSession();
    const result = await this.call(
      'DanePobierzPelnyRaport',
      `<ns:DanePobierzPelnyRaport>`
      + `<ns:pRegon>${escapeXml(regon)}</ns:pRegon>`
      + `<ns:pNazwaRaportu>${escapeXml(reportName)}</ns:pNazwaRaportu>`
      + `</ns:DanePobierzPelnyRaport>`,
    );
    const records = parseDaneRecords(result);
    return records[0] ?? null;
  }
}

/** Dobiera nazwe raportu pelnego na podstawie pol Typ i SilosID z wyszukiwania. */
export function resolveReportName(summary) {
  const type = String(summary?.Typ ?? '').toUpperCase();
  if (type === 'P') return REPORT_NAMES.P;
  if (type === 'LP') return REPORT_NAMES.LP;
  if (type === 'LF') return REPORT_NAMES.LF;
  if (type === 'F') return REPORT_NAMES.F[Number(summary?.SilosID)] ?? REPORT_NAMES.F[6];
  return null;
}

