/**
 * Warstwa wysokopoziomowa: jedna funkcja weryfikujaca REGON/NIP/KRS w bazie GUS.
 */

import { GusClient, GusError, resolveReportName } from './gusClient.js';
import { detectIdentifierType, isValidNip, isValidRegon, normalizeDigits } from './regon.js';

/** Sprowadza rekord z GUS do stabilnego, wlasnego ksztaltu. */
export function normalizeEntity(summary, report) {
  const stripPrefix = (obj) => Object.fromEntries(
    Object.entries(obj ?? {}).map(([key, value]) => [
      key.replace(/^(praw|fiz|lokpraw|lokfiz)_/, ''),
      value,
    ]),
  );
  const detail = stripPrefix(report);
  const pick = (...keys) => {
    for (const key of keys) {
      const value = detail[key] ?? summary?.[key];
      if (value != null && value !== '') return value;
    }
    return null;
  };

  const street = pick('adSiedzUlica_Nazwa', 'Ulica');
  const buildingNo = pick('adSiedzNumerNieruchomosci', 'NrNieruchomosci');
  const flatNo = pick('adSiedzNumerLokalu', 'NrLokalu');

  return {
    regon: pick('regon9', 'regon14', 'Regon'),
    nip: pick('nip', 'Nip'),
    nipStatus: pick('statusNip', 'StatusNip'),
    krs: pick('numerWRejestrzeEwidencji', 'Krs'),
    name: pick('nazwa', 'Nazwa'),
    shortName: pick('nazwaSkrocona'),
    legalFormCode: pick('podstawowaFormaPrawna_Symbol', 'szczegolnaFormaPrawna_Symbol'),
    legalFormName: pick('podstawowaFormaPrawna_Nazwa', 'szczegolnaFormaPrawna_Nazwa'),
    pkdMain: pick('podstawowaFormaPrawna_Symbol_PKD', 'dzialalnoscPodstawowa'),
    startDate: pick('dataRozpoczeciaDzialalnosci', 'dataPowstania'),
    suspendedFrom: pick('dataZawieszeniaDzialalnosci'),
    resumedFrom: pick('dataWznowieniaDzialalnosci'),
    endDate: pick('dataZakonczeniaDzialalnosci', 'DataZakonczeniaDzialalnosci'),
    deletionDate: pick('dataSkresleniaZRegon'),
    address: {
      street: street ? String(street).replace(/^ul\.\s*/i, '') : null,
      buildingNo: buildingNo || null,
      flatNo: flatNo || null,
      postalCode: formatPostalCode(pick('adSiedzKodPocztowy', 'KodPocztowy')),
      city: pick('adSiedzMiejscowosc_Nazwa', 'Miejscowosc'),
      commune: pick('adSiedzGmina_Nazwa', 'Gmina'),
      county: pick('adSiedzPowiat_Nazwa', 'Powiat'),
      voivodeship: pick('adSiedzWojewodztwo_Nazwa', 'Wojewodztwo'),
      country: pick('adSiedzKraj_Nazwa') ?? 'POLSKA',
    },
    type: summary?.Typ ?? null,
    silosId: summary?.SilosID ? Number(summary.SilosID) : null,
  };
}

function formatPostalCode(value) {
  const digits = normalizeDigits(value);
  return digits.length === 5 ? `${digits.slice(0, 2)}-${digits.slice(2)}` : (value || null);
}

/** Podmiot uznajemy za aktywny, gdy nie ma daty zakonczenia/skreslenia ani trwajacego zawieszenia. */
export function isActive(entity) {
  if (entity.endDate || entity.deletionDate) return false;
  if (entity.suspendedFrom && !entity.resumedFrom) return false;
  return true;
}

/**
 * Weryfikuje identyfikator w bazie GUS.
 *
 * @param {string} identifier REGON (9/14), NIP lub KRS
 * @param {object} options
 * @param {string} options.apiKey
 * @param {'prod'|'test'|string} [options.environment='prod']
 * @param {boolean} [options.fullReport=true] pobierz raport szczegolowy
 * @param {GusClient} [options.client] wlasna instancja (pozwala wspoldzielic sesje)
 * @returns {Promise<{valid:boolean, found:boolean, active:boolean|null, identifierType:string|null,
 *   entity:object|null, error:string|null, raw:{summary:object|null, report:object|null}}>}
 */
export async function verifyRegon(identifier, options = {}) {
  const { apiKey, environment = 'prod', fullReport = true, client: providedClient } = options;
  const digits = normalizeDigits(identifier);
  const identifierType = detectIdentifierType(digits);

  const base = {
    valid: false,
    found: false,
    active: null,
    identifierType,
    entity: null,
    error: null,
    raw: { summary: null, report: null },
  };

  if (!identifierType) {
    return { ...base, error: 'Niepoprawny format lub suma kontrolna identyfikatora' };
  }
  base.valid = true;

  const client = providedClient ?? new GusClient({ apiKey, environment });
  const ownsClient = !providedClient;

  try {
    const params = identifierType === 'nip'
      ? { nip: digits }
      : identifierType === 'krs'
        ? { krs: digits }
        : { regon: digits };

    const results = await client.search(params);
    if (results.length === 0) {
      return { ...base, error: 'Nie znaleziono podmiotu w bazie GUS' };
    }

    const summary = results[0];
    base.found = true;
    base.raw.summary = summary;

    let report = null;
    if (fullReport) {
      const reportName = resolveReportName(summary);
      if (reportName) {
        report = await client.fullReport(summary.Regon, reportName);
        base.raw.report = report;
      }
    }

    const entity = normalizeEntity(summary, report);
    return { ...base, entity, active: isActive(entity) };
  } catch (error) {
    if (error instanceof GusError) return { ...base, error: error.message };
    throw error;
  } finally {
    if (ownsClient) {
      await client.logout().catch(() => {});
    }
  }
}

