import { isValidRegon, isValidNip, detectIdentifierType } from './regon.js';
import { parseDaneRecords, unescapeXml } from './xml.js';
import { normalizeEntity, isActive } from './verifyRegon.js';

const checks = [
  ['REGON 9 GUS (000331501)', isValidRegon('000331501') === true],
  ['REGON 9 PKO BP (016298263)', isValidRegon('016298263') === true],
  ['REGON 9 z separatorami', isValidRegon('016-298-263') === true],
  ['REGON 9 bledny', isValidRegon('016298264') === false],
  ['REGON 14 (00033150100000)', isValidRegon('00033150100000') === true],
  ['REGON 14 bledny', isValidRegon('00033150100001') === false],
  ['NIP PKO BP (5250007738)', isValidNip('5250007738') === true],
  ['NIP bledny', isValidNip('5250007739') === false],
  ['detect nip', detectIdentifierType('5250007738') === 'nip'],
  ['detect regon', detectIdentifierType('016298263') === 'regon'],
  ['detect smiec', detectIdentifierType('123') === null],
];

const xml = unescapeXml('&lt;root&gt;&lt;dane&gt;&lt;Regon&gt;016298263&lt;/Regon&gt;&lt;Nazwa&gt;PKO BP S.A.&lt;/Nazwa&gt;&lt;Typ&gt;P&lt;/Typ&gt;&lt;SilosID&gt;6&lt;/SilosID&gt;&lt;NrLokalu /&gt;&lt;/dane&gt;&lt;/root&gt;');
const records = parseDaneRecords(xml);
checks.push(['parse 1 rekord', records.length === 1]);
checks.push(['parse pole Nazwa', records[0].Nazwa === 'PKO BP S.A.']);
checks.push(['parse pusty tag', records[0].NrLokalu === '']);

const entity = normalizeEntity(records[0], {
  praw_regon9: '016298263',
  praw_nazwa: 'POWSZECHNA KASA OSZCZEDNOSCI BANK POLSKI SA',
  praw_adSiedzKodPocztowy: '02515',
  praw_adSiedzMiejscowosc_Nazwa: 'Warszawa',
  praw_adSiedzUlica_Nazwa: 'ul. Pulawska',
  praw_adSiedzNumerNieruchomosci: '15',
  praw_dataZakonczeniaDzialalnosci: '',
});
checks.push(['normalizacja nazwy', entity.name.startsWith('POWSZECHNA')]);
checks.push(['kod pocztowy 02-515', entity.address.postalCode === '02-515']);
checks.push(['ulica bez "ul."', entity.address.street === 'Pulawska']);
checks.push(['aktywny', isActive(entity) === true]);
checks.push(['nieaktywny po dacie konca', isActive({ ...entity, endDate: '2020-01-01' }) === false]);

let failed = 0;
for (const [name, ok] of checks) {
  if (!ok) failed++;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}`);
}
console.log(`\n${checks.length - failed}/${checks.length} przeszlo`);
process.exit(failed ? 1 : 0);

